#include <Arduino.h>
#include <DHT.h>
#include <math.h>

DHT dht(7, DHT11);
unsigned long lastPoll = 0;
unsigned int consecutiveNear = 0;
bool reportedRun = false;

float readDistanceCm() {
  digitalWrite(8, LOW);
  delayMicroseconds(2);
  digitalWrite(8, HIGH);
  delayMicroseconds(10);
  digitalWrite(8, LOW);
  unsigned long duration = pulseIn(9, HIGH, 30000UL);
  if (duration == 0) return NAN;
  return duration / 58.0f;
}

void setup() {
  pinMode(8, OUTPUT);
  digitalWrite(8, LOW);
  pinMode(9, INPUT);
  pinMode(13, OUTPUT);
  digitalWrite(13, LOW);
  Serial.begin(9600);
  dht.begin();
  lastPoll = millis();
}

void loop() {
  unsigned long now = millis();
  if ((unsigned long)(now - lastPoll) < 3000UL) return;
  lastPoll += 3000UL;
  float temperature = dht.readTemperature();
  float distance = readDistanceCm();
  Serial.print("Temperature C: ");
  Serial.println(temperature);
  Serial.print("Distance cm: ");
  Serial.println(distance);
  if (!isnan(distance) && distance < 20.0f) {
    if (consecutiveNear < 3) ++consecutiveNear;
    if (consecutiveNear >= 3) {
      digitalWrite(13, HIGH);
      if (!reportedRun) {
        Serial.println("persistent object detected");
        reportedRun = true;
      }
    }
  } else {
    consecutiveNear = 0;
    reportedRun = false;
  }
}
